1	/**
2	 * E2E test infrastructure for the shared worktree approach.
3	 *
4	 * Two test types:
5	 * - Type A (git operations): init, push, pull — each test creates/destroys its own worktree
6	 * - Type B (tracker operations): create, update, list, etc. — shared long-lived worktree with data reset
7	 *
8	 * IMPORTANT: E2E tests must run serially (not in parallel across files) because
9	 * they share the validation/.agentrack.json pointer file. Use `bun test tests/e2e/`
10	 * and ensure --jobs is 1 if running alongside other tests.
11	 *
12	 * Phase 2 of the E2E refactor spec (.agentic/specs/e2e-refactor.md).
13	 */
14	import { execSync } from "node:child_process";
15	import {
16	  existsSync,
17	  mkdirSync,
18	  readdirSync,
19	  readFileSync,
20	  rmSync,
21	  unlinkSync,
22	  writeFileSync,
23	} from "node:fs";
24	import { join } from "node:path";
25	import { spawn } from "bun";
26	import { expect } from "bun:test";
27	
28	// ─── Constants ───────────────────────────────────────────────────────
29	
30	/** Path to the CLI binary (TypeScript source) */
31	const BIN_PATH = join(import.meta.dir, "..", "..", "src", "bin.ts");
32	
33	/** Branch name for Type B (tracker operation) tests */
34	export const E2E_DATA_BRANCH = "e2edata";
35	
36	/** Branch name for Type A (git operation) tests */
37	export const E2E_GIT_BRANCH = "e2egit";
38	
39	// ─── Path helpers ────────────────────────────────────────────────────
40	
41	let _projectRoot: string | null = null;
42	
43	/** Get the git project root directory. */
44	function getProjectRoot(): string {
45	  if (_projectRoot) return _projectRoot;
46	  _projectRoot = execSync("git rev-parse --show-toplevel", {
47	    encoding: "utf-8",
48	    cwd: import.meta.dir,
49	  }).trim();
50	  return _projectRoot;
51	}
52	
53	let _validationDir: string | null = null;
54	
55	/**
56	 * Get the absolute path to the validation/ directory at the project root.
57	 * Creates it if it doesn't exist.
58	 */
59	export function getValidationDir(): string {
60	  if (_validationDir && existsSync(_validationDir)) return _validationDir;
61	  _validationDir = join(getProjectRoot(), "validation");
62	  if (!existsSync(_validationDir)) {
63	    mkdirSync(_validationDir, { recursive: true });
64	  }
65	  return _validationDir;
66	}
67	
68	/**
69	 * Get the tracker data directory for a branch.
70	 * e.g., for branch "e2edata" -> validation/.e2edata/
71	 */
72	export function getTrackerDir(branch: string): string {
73	  return join(getValidationDir(), `.${branch}`);
74	}
75	
76	/** Derive git branch name from test branch: "e2edata" -> "_e2edata" */
77	function getGitBranch(branch: string): string {
78	  return `_${branch}`;
79	}
80	
81	// ─── CLI helper ──────────────────────────────────────────────────────
82	
83	export interface CLIResult {
84	  stdout: string;
85	  stderr: string;
86	  exitCode: number;
87	}
88	
89	/**
90	 * Run the agt CLI and capture output.
91	 * Defaults cwd to the validation directory.
92	 */
93	export async function runAgt(
94	  args: string[],
95	  cwd?: string,
96	  env?: Record<string, string>,
97	): Promise<CLIResult> {
98	  const dir = cwd ?? getValidationDir();
99	  const proc = spawn({
100	    cmd: ["bun", "run", BIN_PATH, ...args],
101	    cwd: dir,
102	    stdout: "pipe",
103	    stderr: "pipe",
104	    env: { ...process.env, ...env },
105	  });
106	
107	  const stdout = await new Response(proc.stdout).text();
108	  const stderr = await new Response(proc.stderr).text();
109	  const exitCode = await proc.exited;
110	
111	  return { stdout, stderr, exitCode };
112	}
113	
114	// ─── Assertion helpers ───────────────────────────────────────────────
115	
116	/** Parse JSON from CLI output. */
117	// eslint-disable-next-line @typescript-eslint/no-explicit-any
118	export function parseJson(text: string): any {
119	  return JSON.parse(text.trim());
120	}
121	
122	/** Assert CLI result is a success (exit code 0, no stderr, valid JSON on stdout). */
123	export function assertSuccess(result: CLIResult): void {
124	  expect(result.exitCode).toBe(0);
125	  expect(result.stderr).toBe("");
126	  // Verify stdout is valid JSON — different commands return different shapes
127	  const parsed = parseJson(result.stdout);
128	  expect(parsed).toBeDefined();
129	}
130	
131	/** Assert CLI result is an error with the expected code. */
132	export function assertError(
133	  result: CLIResult,
134	  expectedCode: string,
135	  expectedExitCode?: number,
136	): void {
137	  if (expectedExitCode !== undefined) {
138	    expect(result.exitCode).toBe(expectedExitCode);
139	  } else {
140	    expect(result.exitCode).not.toBe(0);
141	  }
142	  const parsed = parseJson(result.stderr);
143	  expect(parsed.result).toBe(expectedCode);
144	}
145	
146	/** Extract the issue ID from a successful create result. */
147	export function extractId(result: CLIResult): string {
148	  const parsed = parseJson(result.stdout);
149	  expect(parsed.id).toBeDefined();
150	  return parsed.id;
151	}
152	
153	// ─── Pre-init helper ────────────────────────────────────────────────
154	
155	/**
156	 * Prepare the validation dir to prevent auto-commits during agt init.
157	 * Pre-creates .gitignore with worktree entry and pointer file so that
158	 * commitGitignoreChange finds nothing to commit.
159	 */
160	function prepareForCleanInit(branch: string): void {
161	  const validationDir = getValidationDir();
162	  const worktreeDir = `.${branch}`;
163	
164	  // Pre-create .gitignore with entry for the worktree dir
165	  const gitignorePath = join(validationDir, ".gitignore");
166	  const entry = `/${worktreeDir}/`;
167	  if (existsSync(gitignorePath)) {
168	    const content = readFileSync(gitignorePath, "utf-8");
169	    if (!content.split("\n").some((line) => line.trim() === entry)) {
170	      const suffix = content.endsWith("\n") ? "" : "\n";
171	      writeFileSync(gitignorePath, content + suffix + entry + "\n");
172	    }
173	  } else {
174	    writeFileSync(gitignorePath, entry + "\n");
175	  }
176	
177	  // Pre-create pointer file (same content that writeBranchPointer writes)
178	  writeFileSync(
179	    join(validationDir, ".agentrack.json"),
180	    JSON.stringify({ branch: getGitBranch(branch) }, null, 2) + "\n",
181	  );
182	}
183	
184	/**
185	 * Ensure the pointer file exists for a given branch.
186	 * Used by Type B tests to restore the pointer after Type A tests may have deleted it.
187	 */
188	export function ensurePointer(branch: string): void {
189	  const validationDir = getValidationDir();
190	  const pointerPath = join(validationDir, ".agentrack.json");
191	  const trackerDir = getTrackerDir(branch);
192	
193	  // Only write pointer if the worktree actually exists
194	  if (existsSync(trackerDir)) {
195	    writeFileSync(
196	      pointerPath,
197	      JSON.stringify({ branch: getGitBranch(branch) }, null, 2) + "\n",
198	    );
199	  }
200	}
201	
202	// ─── Git cleanup helper ─────────────────────────────────────────────
203	
204	/**
205	 * Remove a worktree, local branch, and remote branch.
206	 * All operations are tolerant of missing resources.
207	 */
208	function cleanupWorktree(branch: string): void {
209	  const validationDir = getValidationDir();
210	  const projectRoot = getProjectRoot();
211	  const gitBranch = getGitBranch(branch);
212	  const worktreePath = join(validationDir, `.${branch}`);
213	
214	  // Remove worktree
215	  try {
216	    execSync(`git worktree remove -f "${worktreePath}"`, {
217	      cwd: projectRoot,
218	      stdio: "pipe",
219	    });
220	  } catch {
221	    // Worktree may not exist — ignore
222	  }
223	
224	  // Prune stale worktree entries
225	  try {
226	    execSync("git worktree prune", { cwd: projectRoot, stdio: "pipe" });
227	  } catch {
228	    // Ignore
229	  }
230	
231	  // Delete local branch
232	  try {
233	    execSync(`git branch -D ${gitBranch}`, {
234	      cwd: projectRoot,
235	      stdio: "pipe",
236	    });
237	  } catch {
238	    // Branch may not exist — ignore
239	  }
240	
241	  // Delete remote branch
242	  try {
243	    execSync(`git push origin --delete ${gitBranch}`, {
244	      cwd: projectRoot,
245	      stdio: "pipe",
246	    });
247	  } catch {
248	    // Remote branch may not exist — ignore
249	  }
250	
251	  // Force-remove worktree directory if still present
252	  try {
253	    rmSync(worktreePath, { recursive: true, force: true });
254	  } catch {
255	    // Directory may not exist — ignore
256	  }
257	}
258	
259	// ─── Type A helpers (git operation tests) ────────────────────────────
260	
261	/**
262	 * Initialize a fresh E2E worktree for Type A tests.
263	 * Ensures clean state: removes old worktree/branch, then runs agt init.
264	 */
265	export async function initE2EWorktree(branch: string): Promise<CLIResult> {
266	  const validationDir = getValidationDir();
267	
268	  // Full cleanup of previous state
269	  cleanupWorktree(branch);
270	
271	  // Remove pointer file
272	  try {
273	    rmSync(join(validationDir, ".agentrack.json"), { force: true });
274	  } catch {
275	    // Pointer file may not exist — ignore
276	  }
277	
278	  // Pre-create files to prevent auto-commits on the main branch
279	  prepareForCleanInit(branch);
280	
281	  // Run agt init --branch
282	  return runAgt(["init", "--branch", branch], validationDir);
283	}
284	
285	/**
286	 * Tear down an E2E worktree after a Type A test.
287	 * Removes worktree, branches, and pointer file. Restores Type B pointer
288	 * if the Type B worktree exists.
289	 */
290	export async function teardownE2EWorktree(branch: string): Promise<void> {
